export type VeepooErrorCode =
  | 'UNKNOWN'
  | 'INVALID_ARGUMENT'
  | 'PERMISSION_DENIED'
  | 'CONNECTION_FAILED'
  | 'DISCONNECTION_FAILED'
  | 'BLUETOOTH_NOT_ENABLED'
  | 'DEVICE_NOT_FOUND'
  | 'OPERATION_FAILED'
  | 'SDK_NOT_INITIALIZED'
  | 'DEVICE_NOT_CONNECTED'
  | 'DEVICE_NOT_READY'
  | 'REALTIME_TEST_IN_PROGRESS'
  | 'CAPABILITY_UNSUPPORTED'
  | 'DEVICE_BUSY'
  | 'PASSWORD_REQUIRED'
  | 'TIMEOUT'
  | 'NOT_WEARING';

export interface VeepooError {
  code: VeepooErrorCode;
  message: string;
  /** Raw native rejection code when the bridge collapsed/aliased into `code` (ADR 0003). */
  native_code?: string;
  device_id?: string;
}

export type LogLevel = 'debug' | 'info' | 'warn' | 'error';

export type LogScope =
  | 'sdk'
  | 'scan'
  | 'connection'
  | 'bluetooth'
  | 'permissions'
  | 'device'
  | 'read'
  | 'test'
  | 'listener';

export interface LogEntry {
  timestamp: number;
  level: LogLevel;
  scope: LogScope;
  action: string;
  platform: 'ios' | 'android' | 'web' | 'unknown';
  message: string;
  device_id?: string;
  data?: unknown;
  error?: string;
}

export type LogListener = (entry: LogEntry) => void;
